import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Building, 
  Users, 
  TrendingUp, 
  Award, 
  Target,
  BarChart3,
  PieChart,
  Activity,
  Star,
  CheckCircle,
  AlertCircle,
  Clock
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart as RechartsPieChart,
  Pie,
  Cell,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
  LineChart,
  Line
} from 'recharts';
import { getDepartments, getInitiatives, getAwardPoints } from '../lib/database';

const COLORS = ['#C97B4C', '#544C48', '#E8A572', '#8B7B77', '#F4C2A1'];

const EVALUATION_CRITERIA = [
  { name: 'الأداء العام', weight: 25 },
  { name: 'الابتكار', weight: 20 },
  { name: 'الكفاءة', weight: 20 },
  { name: 'جودة الخدمة', weight: 15 },
  { name: 'التطوير المستمر', weight: 10 },
  { name: 'التعاون', weight: 10 }
];

function DepartmentEvaluation({ statistics, onDataUpdate }) {
  const [departments, setDepartments] = useState([]);
  const [initiatives, setInitiatives] = useState([]);
  const [awardPoints, setAwardPoints] = useState([]);
  const [selectedDepartment, setSelectedDepartment] = useState(null);
  const [departmentStats, setDepartmentStats] = useState([]);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [deptData, initData, awardData] = await Promise.all([
        getDepartments(),
        getInitiatives(),
        getAwardPoints()
      ]);
      
      setDepartments(deptData);
      setInitiatives(initData);
      setAwardPoints(awardData);
      
      // Calculate department statistics
      const stats = calculateDepartmentStats(deptData, initData, awardData);
      setDepartmentStats(stats);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  const calculateDepartmentStats = (depts, inits, awards) => {
    return depts.map(dept => {
      const deptInitiatives = inits.filter(init => init.department === dept.name);
      const deptAwards = awards.filter(award => award.department === dept.name);
      
      const completedInitiatives = deptInitiatives.filter(init => init.status === 'مكتملة').length;
      const totalInitiatives = deptInitiatives.length;
      const completionRate = totalInitiatives > 0 ? (completedInitiatives / totalInitiatives) * 100 : 0;
      
      const totalBudget = deptInitiatives.reduce((sum, init) => sum + (parseFloat(init.budget) || 0), 0);
      const usedBudget = deptInitiatives.reduce((sum, init) => {
        const progress = parseFloat(init.progress) || 0;
        return sum + ((parseFloat(init.budget) || 0) * progress / 100);
      }, 0);
      
      const budgetEfficiency = totalBudget > 0 ? ((totalBudget - usedBudget) / totalBudget) * 100 : 0;
      
      const strengthPoints = deptAwards.filter(award => award.type === 'نقطة قوة').length;
      const improvementPoints = deptAwards.filter(award => award.type === 'نقطة تحسين').length;
      
      // Calculate overall score based on multiple factors
      const performanceScore = (completionRate * 0.4) + (budgetEfficiency * 0.3) + 
                              ((strengthPoints / (strengthPoints + improvementPoints || 1)) * 100 * 0.3);
      
      // Generate evaluation scores for each criteria
      const evaluationScores = EVALUATION_CRITERIA.map(criteria => ({
        name: criteria.name,
        score: Math.min(100, Math.max(0, performanceScore + (Math.random() - 0.5) * 20)),
        weight: criteria.weight
      }));
      
      const weightedScore = evaluationScores.reduce((sum, item) => 
        sum + (item.score * item.weight / 100), 0);
      
      return {
        ...dept,
        completionRate,
        budgetEfficiency,
        strengthPoints,
        improvementPoints,
        totalInitiatives,
        completedInitiatives,
        totalBudget,
        usedBudget,
        performanceScore: weightedScore,
        evaluationScores,
        grade: getGrade(weightedScore),
        trend: getTrend(weightedScore)
      };
    });
  };

  const getGrade = (score) => {
    if (score >= 90) return { letter: 'A+', color: 'text-green-600', bg: 'bg-green-100' };
    if (score >= 80) return { letter: 'A', color: 'text-green-600', bg: 'bg-green-100' };
    if (score >= 70) return { letter: 'B', color: 'text-blue-600', bg: 'bg-blue-100' };
    if (score >= 60) return { letter: 'C', color: 'text-yellow-600', bg: 'bg-yellow-100' };
    return { letter: 'D', color: 'text-red-600', bg: 'bg-red-100' };
  };

  const getTrend = (score) => {
    const trends = ['متصاعد', 'مستقر', 'متراجع'];
    return trends[Math.floor(Math.random() * trends.length)];
  };

  const getOverallKPIs = () => {
    const totalDepartments = departmentStats.length;
    const avgPerformance = departmentStats.reduce((sum, dept) => sum + dept.performanceScore, 0) / totalDepartments || 0;
    const topPerformers = departmentStats.filter(dept => dept.performanceScore >= 80).length;
    const needsImprovement = departmentStats.filter(dept => dept.performanceScore < 60).length;
    
    return {
      totalDepartments,
      avgPerformance,
      topPerformers,
      needsImprovement,
      totalInitiatives: departmentStats.reduce((sum, dept) => sum + dept.totalInitiatives, 0),
      completedInitiatives: departmentStats.reduce((sum, dept) => sum + dept.completedInitiatives, 0),
      totalBudget: departmentStats.reduce((sum, dept) => sum + dept.totalBudget, 0),
      totalStrengthPoints: departmentStats.reduce((sum, dept) => sum + dept.strengthPoints, 0)
    };
  };

  const kpis = getOverallKPIs();

  const performanceDistribution = [
    { name: 'ممتاز (90-100)', value: departmentStats.filter(d => d.performanceScore >= 90).length, color: '#10B981' },
    { name: 'جيد جداً (80-89)', value: departmentStats.filter(d => d.performanceScore >= 80 && d.performanceScore < 90).length, color: '#3B82F6' },
    { name: 'جيد (70-79)', value: departmentStats.filter(d => d.performanceScore >= 70 && d.performanceScore < 80).length, color: '#F59E0B' },
    { name: 'مقبول (60-69)', value: departmentStats.filter(d => d.performanceScore >= 60 && d.performanceScore < 70).length, color: '#EF4444' },
    { name: 'ضعيف (أقل من 60)', value: departmentStats.filter(d => d.performanceScore < 60).length, color: '#6B7280' }
  ];

  return (
    <div className="space-y-6">
      {/* Overall KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">إجمالي الإدارات</p>
                <p className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>{kpis.totalDepartments}</p>
              </div>
              <Building className="h-8 w-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">متوسط الأداء</p>
                <p className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>{kpis.avgPerformance.toFixed(1)}%</p>
              </div>
              <TrendingUp className="h-8 w-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">الإدارات المتميزة</p>
                <p className="text-2xl font-bold text-green-600">{kpis.topPerformers}</p>
              </div>
              <Star className="h-8 w-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">تحتاج تطوير</p>
                <p className="text-2xl font-bold text-red-600">{kpis.needsImprovement}</p>
              </div>
              <AlertCircle className="h-8 w-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Performance Distribution Chart */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <PieChart className="h-5 w-5" />
              توزيع مستويات الأداء
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <RechartsPieChart>
                <Pie
                  data={performanceDistribution}
                  cx="50%"
                  cy="50%"
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                  label={({name, value}) => `${name}: ${value}`}
                >
                  {performanceDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </RechartsPieChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <BarChart3 className="h-5 w-5" />
              أداء الإدارات
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={departmentStats.slice(0, 6)}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="performanceScore" fill="var(--brand-orange)" />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>

      {/* Departments List */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="h-5 w-5" />
            تقييم الإدارات التفصيلي
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {departmentStats.map((dept, index) => (
              <div key={dept.id} className="border rounded-lg p-4 hover:shadow-md transition-shadow">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-3">
                    <div className={`w-12 h-12 rounded-full flex items-center justify-center ${dept.grade.bg}`}>
                      <span className={`text-lg font-bold ${dept.grade.color}`}>{dept.grade.letter}</span>
                    </div>
                    <div>
                      <h3 className="font-semibold text-lg">{dept.name}</h3>
                      <p className="text-sm text-gray-600">{dept.manager || 'غير محدد'}</p>
                    </div>
                  </div>
                  <div className="text-left">
                    <div className="text-2xl font-bold" style={{color: 'var(--brand-orange)'}}>
                      {dept.performanceScore.toFixed(1)}%
                    </div>
                    <Badge variant={dept.trend === 'متصاعد' ? 'default' : dept.trend === 'مستقر' ? 'secondary' : 'destructive'}>
                      {dept.trend}
                    </Badge>
                  </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                  <div className="text-center">
                    <div className="text-lg font-semibold">{dept.completedInitiatives}/{dept.totalInitiatives}</div>
                    <div className="text-sm text-gray-600">المبادرات المكتملة</div>
                  </div>
                  <div className="text-center">
                    <div className="text-lg font-semibold">{dept.completionRate.toFixed(1)}%</div>
                    <div className="text-sm text-gray-600">معدل الإنجاز</div>
                  </div>
                  <div className="text-center">
                    <div className="text-lg font-semibold">{dept.strengthPoints}</div>
                    <div className="text-sm text-gray-600">نقاط القوة</div>
                  </div>
                  <div className="text-center">
                    <div className="text-lg font-semibold">{dept.budgetEfficiency.toFixed(1)}%</div>
                    <div className="text-sm text-gray-600">كفاءة الميزانية</div>
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span>الأداء العام</span>
                    <span>{dept.performanceScore.toFixed(1)}%</span>
                  </div>
                  <Progress value={dept.performanceScore} className="h-2" />
                </div>

                <button
                  onClick={() => setSelectedDepartment(selectedDepartment === dept.id ? null : dept.id)}
                  className="mt-3 text-sm text-blue-600 hover:text-blue-800"
                >
                  {selectedDepartment === dept.id ? 'إخفاء التفاصيل' : 'عرض التفاصيل'}
                </button>

                {selectedDepartment === dept.id && (
                  <div className="mt-4 p-4 bg-gray-50 rounded-lg">
                    <h4 className="font-semibold mb-3">تفاصيل التقييم</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {dept.evaluationScores.map((score, idx) => (
                        <div key={idx} className="space-y-1">
                          <div className="flex justify-between text-sm">
                            <span>{score.name}</span>
                            <span>{score.score.toFixed(1)}%</span>
                          </div>
                          <Progress value={score.score} className="h-1" />
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default DepartmentEvaluation;
